import torch.nn as nn

# PTX source for a naive fp16 matrix multiplication (C = A @ B)
PTX_SOURCE = r'''
.version 8.0
.target sm_80
.address_size 64

.visible .entry kernel_matmul(
    .param .u64 A,
    .param .u64 B,
    .param .u64 C,
    .param .u32 N
)
{
    .reg .u64 %a_ptr, %b_ptr, %c_ptr;
    .reg .u32 %n;
    ld.param.u64 %a_ptr, [A];
    ld.param.u64 %b_ptr, [B];
    ld.param.u64 %c_ptr, [C];
    ld.param.u32 %n, [N];

    .reg .u32 %tid_x, %tid_y, %bid_x, %bid_y;
    mov.u32 %tid_x, %tid.x;
    mov.u32 %tid_y, %tid.y;
    mov.u32 %bid_x, %ctaid.x;
    mov.u32 %bid_y, %ctaid.y;

    .reg .u32 %row, %col;
    mad.lo.u32 %row, %bid_y, 16, %tid_y;   // row = blockIdx.y * 16 + threadIdx.y
    mad.lo.u32 %col, %bid_x, 16, %tid_x;   // col = blockIdx.x * 16 + threadIdx.x

    // Bounds check
    .reg .pred %p_exit, %p_exit2;
    setp.ge.u32 %p_exit, %row, %n;
    setp.ge.u32 %p_exit2, %col, %n;
    or.pred %p_exit, %p_exit, %p_exit2;
    @%p_exit ret;

    .reg .f32 %acc;
    mov.f32 %acc, 0f0;

    .reg .u32 %k, %r_tmp, %r_tmp2;
    .reg .pred %p_done;
    .reg .u64 %addr_a, %addr_b, %addr_c;
    .reg .u16 %a_half, %b_half;
    .reg .f32 %a_f32, %b_f32;

    // Compute address of C[row, col]
    mul.lo.u32 %r_tmp, %row, %n;
    add.u32 %r_tmp, %r_tmp, %col;
    mul.wide.u32 %addr_c, %r_tmp, 2;          // * sizeof(half)
    add.u64 %addr_c, %c_ptr, %addr_c;

    mov.u32 %k, 0;
LOOP_START:
    setp.ge.u32 %p_done, %k, %n;
    @%p_done bra LOOP_END;

    // Address of A[row, k]
    mul.lo.u32 %r_tmp, %row, %n;
    add.u32 %r_tmp, %r_tmp, %k;
    mul.wide.u32 %addr_a, %r_tmp, 2;
    add.u64 %addr_a, %a_ptr, %addr_a;

    // Address of B[k, col]
    mul.lo.u32 %r_tmp2, %k, %n;
    add.u32 %r_tmp2, %r_tmp2, %col;
    mul.wide.u32 %addr_b, %r_tmp2, 2;
    add.u64 %addr_b, %b_ptr, %addr_b;

    // Load half values
    ld.global.u16 %a_half, [%addr_a];
    ld.global.u16 %b_half, [%addr_b];

    // Convert to fp32
    cvt.f32.f16 %a_f32, %a_half;
    cvt.f32.f16 %b_f32, %b_half;

    // Accumulate
    fma.rn.f32 %acc, %a_f32, %b_f32, %acc;

    add.u32 %k, %k, 1;
    bra LOOP_START;
LOOP_END:

    // Convert result back to half and store
    cvt.rn.f16.f32 %a_half, %acc;
    st.global.u16 [%addr_c], %a_half;

    ret;
}
'''

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # Load PTX module using the provided harness API
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        N = A.shape[0]
        C = torch.empty_like(A)

        # Launch configuration: 16x16 threads per block
        block = (16, 16, 1)
        grid = ((N + 15) // 16, (N + 15) // 16)

        # Arguments: raw pointers and dimension size
        args = [A.data_ptr(), B.data_ptr(), C.data_ptr(), N]

        # Launch the kernel via the harness
        ptx_launch(self.module, "kernel_matmul", grid, block, args)

        return C
